/**
 * Merges multiple objects with special handling for options
 * @param {...Object} args - Objects to merge. The last argument can contain an `options` property
 * @returns {Object} Merged object with options spread into the result
 * @example
 * mergeOpts({ a: 1 }, { options: { b: 2 }, c: 3 })
 * // Returns: { a: 1, b: 2, c: 3 }
 */
export function mergeOpts(...args) {
  const props = args[args.length - 1]
  const { options = {}, ...rest } = props
  return Object.assign({}, ...args.slice(0, -1), options, rest)
}
